inline double Predict(double speed, double acceleration, double pitch)
{
    std::array<double, 3> input{{speed, acceleration, pitch}};
    for (std::size_t i = 0; i < input.size(); ++i) {
        input[i] = (input[i] - detail::kInputMean[i]) / detail::kInputScale[i];
    }

    std::array<double, 16> hidden1{};
    for (std::size_t i = 0; i < hidden1.size(); ++i) {
        double sum = detail::kLayer1Bias[i];
        for (std::size_t j = 0; j < input.size(); ++j) {
            sum += detail::kLayer1Weights[i][j] * input[j];
        }
        hidden1[i] = std::tanh(sum);
    }

    std::array<double, 16> hidden2{};
    for (std::size_t i = 0; i < hidden2.size(); ++i) {
        double sum = detail::kLayer2Bias[i];
        for (std::size_t j = 0; j < hidden1.size(); ++j) {
            sum += detail::kLayer2Weights[i][j] * hidden1[j];
        }
        hidden2[i] = std::tanh(sum);
    }

    double output = detail::kOutputBias;
    for (std::size_t i = 0; i < hidden2.size(); ++i) {
        output += detail::kOutputWeights[i] * hidden2[i];
    }
    return output * detail::kTargetScale + detail::kTargetMean;
}

